From da1f5f5f783e8b1551d4632ae7b78f9e7932e35a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:23:17 +0100
Subject: [PATCH] containments/desktop: show app names for launchers in custom
 folders

Launchers were only labelled with their Name on desktop:/, so a desktop
set to any other folder showed file names. Now the desktop reads Name
once per listed launcher and uses it for labels, sorting and renaming.

BUG: 511746
---
 .../package/contents/ui/FolderView.qml        |  2 +-
 .../desktop/plugins/folder/foldermodel.cpp    | 85 ++++++++++++++++++-
 .../desktop/plugins/folder/foldermodel.h      |  3 +
 3 files changed, 87 insertions(+), 3 deletions(-)

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
index b858d16f7a..656cfec133 100644
--- a/containments/desktop/package/contents/ui/FolderView.qml
+++ b/containments/desktop/package/contents/ui/FolderView.qml
@@ -1228,7 +1228,7 @@ FocusScope {
             usedByContainment: root.isContainment && main.isRootView
             sortDesc: Plasmoid.configuration.sortDesc
             sortDirsFirst: Plasmoid.configuration.sortDirsFirst
-            parseDesktopFiles: (Plasmoid.configuration.url === "desktop:/")
+            parseDesktopFiles: root.isContainment || Plasmoid.configuration.url === "desktop:/"
             previews: Plasmoid.configuration.previews
             previewPlugins: Plasmoid.configuration.previewPlugins
             applet: Plasmoid
diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..200e3e595a 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -94,6 +94,11 @@

 using namespace std::chrono_literals;

+static bool isLocalDesktopFile(const KFileItem &item)
+{
+    return item.url().isLocalFile() && item.isRegularFile() && KDesktopFile::isDesktopFile(item.localPath());
+}
+
 KRunnerChecker::KRunnerChecker(QObject *parent)
     : QObject(parent)
     , m_krunnerAvailable(false)
@@ -226,6 +231,22 @@ FolderModel::FolderModel(QObject *parent)
     connect(dirLister, &DirLister::error, this, &FolderModel::dirListFailed);
     connect(dirLister, &KCoreDirLister::itemsDeleted, this, &FolderModel::evictFromIsDirCache);

+    // Connected before KDirModel's own connections, so names are current when it signals the change.
+    connect(dirLister, &KCoreDirLister::itemsAdded, this, [this](const QUrl &, const KFileItemList &items) {
+        updateDesktopFileNames(items);
+    });
+    connect(dirLister, &KCoreDirLister::refreshItems, this, [this](const QList<QPair<KFileItem, KFileItem>> &items) {
+        KFileItemList newItems;
+        for (const auto &[oldItem, newItem] : items) {
+            m_desktopFileNames.remove(oldItem.url());
+            newItems.append(newItem);
+        }
+        updateDesktopFileNames(newItems);
+    });
+    connect(dirLister, qOverload<>(&KCoreDirLister::clear), this, [this] {
+        m_desktopFileNames.clear();
+    });
+
     connect(dirLister, &KCoreDirLister::started, this, std::bind(&FolderModel::setStatus, this, Status::Listing));

     QObject::connect(dirLister, &KCoreDirLister::completed, this, [this, dirLister] {
@@ -646,6 +667,9 @@ void FolderModel::setParseDesktopFiles(bool enable)
 {
     if (m_parseDesktopFiles != enable) {
         m_parseDesktopFiles = enable;
+        m_desktopFileNames.clear();
+        updateDesktopFileNames(m_dirModel->dirLister()->items());
+        invalidateIfComplete();
         Q_EMIT parseDesktopFilesChanged();
     }
 }
@@ -933,6 +957,32 @@ void FolderModel::rename(int row, const QString &name)
     }

     const KFileItem oldItem = itemForIndex(idx);
+    if (m_parseDesktopFiles && isLocalDesktopFile(oldItem)) {
+        if (name.isEmpty() || name == itemText(oldItem)) {
+            return;
+        }
+
+        // Change the Name like the desktop:/ worker does, using a writable copy if needed.
+        const QString path = oldItem.localPath();
+        if (!QFileInfo(path).isWritable()) {
+            KDesktopFile orig(path);
+            QFile(path).remove();
+            const QString newPath = QStandardPaths::writableLocation(QStandardPaths::ApplicationsLocation) + QDir::separator() + oldItem.name();
+            if (!QFileInfo::exists(newPath)) {
+                auto writableDesktopFile = orig.copyTo(newPath);
+                writableDesktopFile->sync();
+                delete writableDesktopFile;
+            }
+            QFile::link(newPath, path);
+        }
+
+        KDesktopFile file(path);
+        KConfigGroup group = file.desktopGroup();
+        group.writeEntry("Name", name);
+        group.writeEntry("Name", name, KConfigGroup::Persistent | KConfigGroup::Localized);
+        group.sync();
+        return;
+    }
     if (name.isEmpty() || name == oldItem.text() || name == QLatin1Char('.') || name == QLatin1String("..")) {
         return;
     }
@@ -1540,6 +1590,8 @@ QVariant FolderModel::data(const QModelIndex &index, int role) const

     if (role == BlankRole) {
         return m_dragIndexes.contains(index);
+    } else if (role == Qt::DisplayRole && index.column() == KDirModel::Name) {
+        return itemText(itemForIndex(index));
     } else if (role == SelectedRole) {
         return m_selectionModel->isSelected(index);
     } else if (role == IsDirRole) {
@@ -1575,7 +1627,7 @@ QVariant FolderModel::data(const QModelIndex &index, int role) const
     } else if (role == FileNameRole) {
         return itemForIndex(index).url().fileName();
     } else if (role == FileNameWrappedRole) {
-        return KStringHandler::preProcessWrap(itemForIndex(index).text());
+        return KStringHandler::preProcessWrap(itemText(itemForIndex(index)));
     }

     return QSortFilterProxyModel::data(index, role);
@@ -1591,6 +1643,34 @@ KFileItem FolderModel::itemForIndex(const QModelIndex &index) const
     return m_dirModel->itemForIndex(mapToSource(index));
 }

+void FolderModel::updateDesktopFileNames(const KFileItemList &items)
+{
+    if (!m_parseDesktopFiles) {
+        return;
+    }
+
+    for (const KFileItem &item : items) {
+        if (isLocalDesktopFile(item)) {
+            const QString name = KDesktopFile(item.localPath()).readName();
+            if (!name.isEmpty()) {
+                m_desktopFileNames.insert(item.url(), name);
+                continue;
+            }
+        }
+        m_desktopFileNames.remove(item.url());
+    }
+}
+
+QString FolderModel::itemText(const KFileItem &item) const
+{
+    const auto it = m_desktopFileNames.constFind(item.url());
+    if (it != m_desktopFileNames.constEnd()) {
+        return *it;
+    }
+
+    return item.text();
+}
+
 bool FolderModel::isDir(const QModelIndex &index, const KDirModel *dirModel) const
 {
     KFileItem item = dirModel->itemForIndex(index);
@@ -1664,6 +1744,7 @@ void FolderModel::evictFromIsDirCache(const KFileItemList &items)
     for (const KFileItem &item : items) {
         m_screenMapper->removeFromMap(item.url(), m_currentActivity);
         m_isDirCache.remove(item.url());
+        m_desktopFileNames.remove(item.url());
         Q_EMIT itemDeleted(item.url());
     }
 }
@@ -1733,7 +1814,7 @@ bool FolderModel::lessThan(const QModelIndex &left, const QModelIndex &right) co

     QCollator collator;

-    result = collator.compare(leftItem.text(), rightItem.text());
+    result = collator.compare(itemText(leftItem), itemText(rightItem));

     if (result != 0)
         return result < 0;
