+++ b/containments/desktop/plugins/folder/foldermodel.h
@@ -364,6 +364,8 @@ private:
     void createActions();
     void addDragImage(QDrag *drag, int x, int y);
     void setStatus(Status status);
+    void updateDesktopFileNames(const KFileItemList &items);
+    QString itemText(const KFileItem &item) const;
     bool renameTargetStillMatches(const QUrl &oldUrl, const QString &expectedName) const;
     static bool isTrashEmpty();
     static bool isDeleteCommandShown();
@@ -373,6 +375,7 @@ private:
     QString m_url;
     mutable QHash<QUrl, bool> m_isDirCache;
     mutable QHash<QUrl, KIO::StatJob *> m_isDirJobs;
+    QHash<QUrl, QString> m_desktopFileNames;
     QItemSelectionModel *m_selectionModel;
     QItemSelection m_pinnedSelection;
     QModelIndexList m_dragIndexes;
